/**
 * @name Command Injection Broad
 * @description Detects command injection vulnerabilities from CLI args or Env vars to subprocess calls.
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-broad
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module CommandInjectionBroadConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // sys.argv
    source = API::moduleImport("sys").getMember("argv").asSource()
    or
    // os.environ
    source = API::moduleImport("os").getMember("environ").asSource()
    or
    // argparse
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("argparse").getMember("ArgumentParser").getACall().getReturn().getMember("parse_args").getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "run", "Popen"]).getACall()
        or
        call = API::moduleImport("os").getMember(["system", "popen"]).getACall()
      ) and
      (
        sink = call.getArg(_) or
        sink = call.getArgByName(_)
      )
    )
  }
}

module CommandInjectionBroadFlow = TaintTracking::Global<CommandInjectionBroadConfig>;
import CommandInjectionBroadFlow::PathGraph

from CommandInjectionBroadFlow::PathNode source, CommandInjectionBroadFlow::PathNode sink
where CommandInjectionBroadFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential command injection from $@.", source.getNode(), "user input"
